CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260531034635_InitialCreate') THEN
    CREATE TABLE "Clientes" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" text NOT NULL,
        "Cedula" text NOT NULL,
        no_tarjeta_cr char(4) NOT NULL,
        "LimiteCredito" numeric(10,2) NOT NULL DEFAULT 0.0,
        "TipoPersona" text NOT NULL,
        fecha_creacion timestamptz NOT NULL DEFAULT (now()),
        fecha_modificacion timestamptz,
        usuario_creacion text NOT NULL,
        usuario_modificacion text,
        "Estado" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id"),
        CONSTRAINT "CK_Clientes_NoTarjetaCr" CHECK (no_tarjeta_cr ~ '^[0-9]{4}$')
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260531034635_InitialCreate') THEN
    CREATE TABLE "Elenco" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "Nombre" text NOT NULL,
