DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260531034635_InitialCreate') THEN
    CREATE TABLE "Articulos" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "Titulo" text NOT NULL,
        "TipoArticuloId" bigint NOT NULL,
        "GeneroId" bigint NOT NULL,
        "IdiomaId" bigint NOT NULL,
        renta_por_dia numeric(10,2) NOT NULL,
        "DiasRenta" integer NOT NULL DEFAULT 3,
        "MontoEntregaTardia" numeric(10,2) NOT NULL DEFAULT 0.0,
        "Stock" integer NOT NULL DEFAULT 0,
        fecha_creacion timestamptz NOT NULL DEFAULT (now()),
        fecha_modificacion timestamptz,
        usuario_creacion text NOT NULL,
        usuario_modificacion text,
        "Estado" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_Articulos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Articulos_Generos_GeneroId" FOREIGN KEY ("GeneroId") REFERENCES "Generos" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Articulos_Idiomas_IdiomaId" FOREIGN KEY ("IdiomaId") REFERENCES "Idiomas" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_Articulos_TiposArticulos_TipoArticuloId" FOREIGN KEY ("TipoArticuloId") REFERENCES "TiposArticulos" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

