        CONSTRAINT "FK_ElencoArticulo_Elenco_ElencoId" FOREIGN KEY ("ElencoId") REFERENCES "Elenco" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_ElencoArticulo_RolesElenco_RolElencoId" FOREIGN KEY ("RolElencoId") REFERENCES "RolesElenco" ("Id") ON DELETE CASCADE
