    CREATE TABLE "RentaDevolucion" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "NoRenta" text NOT NULL,
        "EmpleadoId" bigint NOT NULL,
        "ArticuloId" bigint NOT NULL,
        "ClienteId" bigint NOT NULL,
        fecha_renta timestamptz NOT NULL DEFAULT (now()),
        fecha_devolucion timestamptz,
        "MontoXdia" numeric(10,2) NOT NULL,
        cantidad_dias integer NOT NULL,
        "DiasRetraso" integer NOT NULL DEFAULT 0,
        "Comentario" text,
        fecha_creacion timestamptz NOT NULL DEFAULT (now()),
        fecha_modificacion timestamptz,
        usuario_creacion text NOT NULL,
        usuario_modificacion text,
        "Estado" boolean NOT NULL DEFAULT TRUE,
        CONSTRAINT "PK_RentaDevolucion" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_RentaDevolucion_Articulos_ArticuloId" FOREIGN KEY ("ArticuloId") REFERENCES "Articulos" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_RentaDevolucion_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_RentaDevolucion_Empleados_EmpleadoId" FOREIGN KEY ("EmpleadoId") REFERENCES "Empleados" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

